const mines = new Set(["0,0"]);
let safe = [];
for (let r=0;r<game.rows;r++) for (let c=0;c<game.cols;c++) if (!mines.has(r+","+c)) safe.push([r,c]);
let actions=[];
let progress=true;
while (progress && game.summary().status==="playing") {
  progress=false;
  for (const [r,c] of safe) {
    const v=game.view()[r][c];
    if (v==="#" ) {
      const x=game.reveal(r,c);
      actions.push("G"+r+","+c);
      if (x.hitMine) { mines.add(r+","+c); progress=true; break; }
      progress=true;
    }
    if (game.summary().status!=="playing") break;
  }
}
return {actions, mines:[...mines], board:game.text(), ...game.summary()};

